@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap');

:root {
  --glitz-dark: #0D1C1E;
  --glitz-emerald: #1D3D40;
  --glitz-gold: #C5A880;
  --glitz-gold-light: #DFCEB8;
  --glitz-border: #E5EAE9;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif !important;
  background-color: #FFFFFF !important;
  color: #182324 !important;
  -webkit-font-smoothing: antialiased;
}

.section-navigation-bar {
  background: #122628 !important;
  color: #DFCEB8 !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  letter-spacing: 0.08em !important;
}

.section-header {
  border-bottom: 1px solid #E5EAE9 !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.03) !important;
}

/* FIX DUPLICATED LOGO TEXT */
.logo-text-container a.logo-text h1.logo-text {
  display: none !important;
}

.logo-text-container a.logo-text {
  font-size: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  text-decoration: none !important;
  line-height: 1 !important;
}

.logo-text-container a.logo-text::after {
  content: "✦ GLITZ PERFUMARIA" !important;
  font-family: 'Plus Jakarta Sans', sans-serif !important;
  font-size: 1.45rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.16em !important;
  background: linear-gradient(135deg, #1D3D40 0%, #C5A880 100%) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
}

/* Clean Desktop Navigation Bar */
.js-nav-desktop-container {
  visibility: visible !important;
  height: auto !important;
  display: block !important;
  margin-top: 8px !important;
}

.nav-desktop-list {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 8px !important;
}

.nav-desktop-list a {
  font-family: 'Plus Jakarta Sans', sans-serif !important;
  font-size: 11.5px !important;
  font-weight: 700 !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
  color: #1D3D40 !important;
  padding: 8px 12px !important;
  transition: all 0.2s ease !important;
}

.nav-desktop-list a:hover {
  color: #C5A880 !important;
}

.section-footer {
  background: #0D1C1E !important;
  color: rgba(255, 255, 255, 0.8) !important;
  border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
}

.section-footer a {
  color: rgba(255, 255, 255, 0.7) !important;
  text-decoration: none !important;
}

.section-footer a:hover {
  color: #DFCEB8 !important;
}

.section-custom {
  padding: 0 !important;
  margin: 0 !important;
}

/* --- GLITZ PERFUMARIA AI LOGO --- */
.logo-text-container a.logo-text,
a.logo-text,
.header-logo a {
  display: inline-block !important;
  width: 290px !important;
  height: 70px !important;
  background-image: url('https://raw.githubusercontent.com/lian-v4/glitz-template/main/static/images/logo-glitz-header-verde.png') !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  text-indent: -9999px !important;
  overflow: hidden !important;
  font-size: 0 !important;
  transition: transform 0.2s ease;
}

.logo-text-container a.logo-text:hover,
a.logo-text:hover,
.header-logo a:hover {
  transform: scale(1.02);
}

.logo-text-container a.logo-text h1.logo-text,
.logo-text-container a.logo-text span,
a.logo-text h1 {
  display: none !important;
}

@media (max-width: 768px) {
  .logo-text-container a.logo-text,
  a.logo-text,
  .header-logo a {
    width: 210px !important;
    height: 52px !important;
  }
}
}


/* --- GLITZ PRODUCT DETAIL PAGE SIZING --- */
.section-main-product,
.main-product,
[data-section-type="main-product"] {
  max-width: 1280px !important;
  margin: 0 auto !important;
  padding: 30px 20px 60px 20px !important;
}

.product-images,
.js-product-images,
[data-block-type="product-media"] {
  max-width: 480px !important;
  margin: 0 auto !important;
}

.product-images-slider,
.product-image-container,
.product-image,
.swiper-slide-product {
  max-height: 480px !important;
  border-radius: 12px !important;
  overflow: hidden !important;
}

.product-image img,
.product-images-slider img,
.product-slider img,
.swiper-slide-product img,
.product-images img {
  max-height: 460px !important;
  width: auto !important;
  max-width: 100% !important;
  object-fit: contain !important;
  margin: 0 auto !important;
  display: block !important;
}

@media (max-width: 768px) {
  .product-images,
  .js-product-images,
  [data-block-type="product-media"] {
    max-width: 100% !important;
  }
  .product-image img,
  .product-images-slider img,
  .product-images img {
    max-height: 320px !important;
  }
}

